## 4. 实体遍历 + 绘制管线

```cpp
constexpr uintptr_t OFF_ENTITY_LIST   = 0x000000;  // ← CE 标定后填入
constexpr uintptr_t OFF_ENTITY_COUNT  = 0x000004;
constexpr uintptr_t OFF_ENTITY_STRIDE = 8;
constexpr uintptr_t OFF_LOCAL_PAWN    = 0x000008;
constexpr uintptr_t OFF_POS           = 0x000120;
constexpr uintptr_t OFF_HP            = 0x000140;
constexpr uintptr_t OFF_TEAM          = 0x000144;
constexpr uintptr_t OFF_VIEW_MATRIX   = 0x000200;

struct Player { Vec3 pos; int hp; int team; };

std::vector<Player> Collect(const GameReader& gr) {
    std::vector<Player> out;
    uintptr_t list = gr.Read<uintptr_t>(gr.base() + OFF_ENTITY_LIST);
    int count      = gr.Read<int>(gr.base() + OFF_ENTITY_COUNT);
    uintptr_t self = gr.Read<uintptr_t>(gr.base() + OFF_LOCAL_PAWN);
    if (!list || count <= 0 || count > 512) return out;

    int selfTeam = self ? gr.Read<int>(self + OFF_TEAM) : -1;
    out.reserve(count);
    for (int i = 0; i < count; ++i) {
        uintptr_t e = gr.Read<uintptr_t>(list + i * OFF_ENTITY_STRIDE);
        if (!e || e == self) continue;
        Player p;
        p.hp   = gr.Read<int>(e + OFF_HP);
        p.team = gr.Read<int>(e + OFF_TEAM);
        p.pos  = gr.Read<Vec3>(e + OFF_POS);
        if (p.hp <= 0 || p.team == selfTeam) continue;
        if (!(p.pos.x > -1e7 && p.pos.x < 1e7)) continue;   // 脏数据过滤
        out.push_back(p);
    }
    return out;
}
